    <!-- 症状区域：显示部位相关症状 -->
    <div class="symptoms-container">
      <div v-if="selectedPart" class="part-symptoms">
        <template v-if="filteredSymptoms.length > 0">
          <h5>{{ bodyPartLabels[selectedPart] }} 相关症状</h5>
          <div class="symptom-chips">
            <button
              v-for="symptom in filteredSymptoms"
              :key="symptom.key"
              type="button"
              :class="['symptom-chip', { active: isSymptomSelected(symptom.key) }]"
              :aria-pressed="isSymptomSelected(symptom.key)"
              @click="handleSymptomClick(symptom)"
            >
              {{ symptom.name }}
            </button>
          </div>
        </template>
        <div v-else class="no-symptoms">暂无该部位相关症状</div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, nextTick, onMounted, PropType, useTemplateRef, watch } from 'vue';

interface Symptom {
  key: string;
  name: string;
  bodyParts: string[];
  systemCategory: string[];
}

const props = defineProps({
  symptoms: {
    type: Array as PropType<Symptom[]>,
    required: true
  },
  patientGender: {
    type: String as PropType<'male' | 'female'>,
    default: 'male'
  },
  selectedSymptoms: {
    type: Array as PropType<{ key: string }[]>,
    default: () => []
  }
});

const emit = defineEmits<{
  (e: 'select-symptom', symptom: Symptom): void;
}>();

const handleSymptomClick = (symptom: Symptom) => {
  emit('select-symptom', symptom);
};

// 根据患者性别自动设置
const gender = ref<'male' | 'female'>(props.patientGender);
const viewMode = ref<'front' | 'back'>('front');
const selectedPart = ref<string | null>(null);
const bodyViewRef = useTemplateRef<HTMLElement>('bodyView');

// 监听患者性别变化
watch(() => props.patientGender, (newGender) => {
  gender.value = newGender;
});

const bodyPartLabels: Record<string, string> = {
  head: '头部',
  neck: '颈部',
  chest: '胸部',
  abdomen: '腹部',
  back: '背部',
  buttock: '臀部',
  genital: '生殖器',
  upper_limb: '上肢',
  lower_limb: '下肢'
};

// ID 映射：SVG中的ID -> 我们的body part key
const partIdMap: Record<string, string> = {
  '1-4-头部': 'head',
  '2-61-头部': 'head',
  '1-16-颈部': 'neck',
  '1-3-后颈部': 'neck',
  '2-73-颈部': 'neck',
  '2-60-后颈部': 'neck',
  '1-18-胸部': 'chest',
  '2-75-胸部': 'chest',
  '1-35-腹部': 'abdomen',
  '2-92-腹部': 'abdomen',
  '1-31-背部': 'back',
  '2-88-背部': 'back',
  '1-48-臀部': 'buttock',
  '2-106-臀部': 'buttock',
  '1-44-生殖器': 'genital',
  '2-101-生殖器': 'genital',
  '1-25-上肢': 'upper_limb',
  '2-82-上肢': 'upper_limb',
  '1-51-下肢': 'lower_limb',
  '2-109-下肢': 'lower_limb',
  '1-2-枕部': 'head',
  '2-59-枕部': 'head'
};

const selectPart = (svgId: string) => {
  const part = partIdMap[svgId];
  if (part) {
    if (selectedPart.value === part) {
      selectedPart.value = null;
    } else {
      selectedPart.value = part;
    }
    // 手动更新 SVG 元素的高亮状态
    updateSVGHighlight();
  }
};

const updateSVGHighlight = () => {
  const svg = bodyViewRef.value?.querySelector('.body-svg');
  if (!svg) return;

  // 移除所有已有的高亮
  svg.querySelectorAll('.body-part-group').forEach((group) => {
    group.classList.remove('active');
    const id = group.querySelector<SVGElement>('[id]')?.id;
    const part = id ? partIdMap[id] : null;
    if (!part) return;
    group.setAttribute('role', 'button');
    group.setAttribute('tabindex', '0');
    group.setAttribute('aria-label', `选择${bodyPartLabels[part]}`);
    group.setAttribute('aria-pressed', String(part === selectedPart.value));
  });

  // 找到当前选中部位对应的所有 SVG ID，添加高亮
  if (selectedPart.value) {
    Object.entries(partIdMap).forEach(([id, partKey]) => {
      if (partKey === selectedPart.value) {
        const element = svg.querySelector(`#${CSS.escape(id)}`);
        const group = element?.closest('.body-part-group');
        if (group) {
          group.classList.add('active');
        }
      }
    });
  }
};

const clearSelection = () => {
  selectedPart.value = null;
  updateSVGHighlight();
};

const filteredSymptoms = computed(() => {
  if (!selectedPart.value) return [];
  return props.symptoms.filter(symptom =>
    symptom.bodyParts.includes(selectedPart.value!)
  );
});

// 检查症状是否已被选中
const isSymptomSelected = (key: string) => {
  return props.selectedSymptoms.some(s => s.key === key);
};

// SVG 内容
